import sys

MOD = 10**9 + 7

def main():
    import sys
    sys.setrecursionlimit(1 << 25)
    n = int(input())
    a = list(map(int, input().split()))

    # Function to count the number of perfect squares less than x
    def perfect_squares(x):
        count = 0
        i = 1
        while i*i < x:
            count += 1
            i += 1
        return count

    freq = [0] * 3
    for num in a:
        count = perfect_squares(num)
        if count == 0:
            freq[0] += 1
        elif count % 2 == 1:
            freq[1] += 1
        else:
            freq[2] += 1

    # Using multinomial coefficient via dynamic programming
    dp = [0] * (max(freq) + 1)
    dp[0] = 1
    for i in range(1, max(freq) + 1):
        for j in range(i+1):
            if freq[i-j] > 0:
                dp[i] = (dp[i] + dp[i-j]) % MOD
    print(dp[max(freq)])

