def solution(input_string):
    n, m, k = map(int, input_string.readline().split())
    fires = [tuple(map(int, input_string.readline().split())) for _ in range(k)]

    distance = []
    for xi, yi in fires:
        for dx in (-1, 1, 0, 0):
            if dx == 0: continue
            ny = yi + (xi - xi) // dx  # ensures eastern or western direction
            if 1 <= nx := xi + dx <= n and 1 <= ny <= m:
                distance.append((xi - nx) ** 2 + (yi - ny) ** 2)
        for dy in (-1, 1, 0, 0):
            if dy == 0: continue
            nx = xi + (yi - yi) // dy
            if 1 <= nx <= n and 1 <= ny := yi + dy <= m:
                distance.append((xi - nx) ** 2 + (yi - ny) ** 2)
    distance.sort()
    print(2 * math.sqrt(1 + distance[-1]), end='')

