        edges[u - 1].append(v - 1)
        edges[v - 1].append(u - 1)

    size = 1
    while size < n:
        size <<= 1
    seg = [0] * (2 * size)

    # build segment tree for counting nodes
    def count_nodes(pos):
        cnt = 0
        for i in range(size):
            cnt += seg[size + i]
        return cnt
    def update(pos, val):
        while pos < size:
            seg[pos] += val
            pos += pos & -pos

    for i in range(n):
        update(i, 1)
        for u in edges[i]:
            update(i, -1)
    for i in range(size):
        seg[size + i] = count_nodes(i)

    # depth vectors for each node
    depth = [0] * n
    def dfs(u, d):
        depth[u] = d
        for v in edges[u]:
            dfs(v, d + 1)
    dfs(0, 0)

