            while sig[u] > sig[v]:
                u = parent[u]
            while sig[v] > sig[u]:
                v = parent[v]
            if u != v:
                u = parent[u]
                v = parent[v]
            return u
        lca = get_lca(l, r)
        max_level_lca = max_level[lca]
        reachable_employees = []
        if lca == l:
            reachable_employees = list(range(l, r + 1))
            if max_level[lca] == max_level[l]:
                reachable_employees = [l]
        elif lca == r:
