import sys

def solution(input_data):
    sys.setrecursionlimit(10**6)
    lines = input_data.strip().split('\n')
    n, k = map(int, lines[0].split())
    edges = [tuple(map(int, line.split())) for line in lines[1:]]

    edges.sort(key=lambda x: x[0])
    adjacency = [[] for _ in range(n + 1)]
    for u, v in edges:
        adjacency[u].append(v)
        adjacency[v].append(u)

    # Kruskal's algorithm to find MIS
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if rank[root_u] < rank[root_v]:
            parent[root_u] = root_v
        elif rank[root_u] > rank[root_v]:
            parent[root_v] = root_u
        else:
            parent[root_v] = root_u
            rank[root_u] += 1

    for u, v in edges:
        if find(u) != find(v):
            union(u, v)

    # Find MIS nodes
    mis_nodes = [u for u in range(1, n + 1) if find(u) == u]

    # Assign each node to a group
    groups = [[u] for u in range(1, n + 1)]
    for u in mis_nodes:
        groups.append([u])

    # Remove MIS from adjacency to get other groups
    for node in mis_nodes:
        for adj in adjacency[node]:
            groups[adj].append(node)

    # Count crossing edges (`edges` between different groups)
    crossing_edges = 0
    for i, group_a in enumerate(groups):
        for u in group_a:
            for v in adjacency[u]:
                if v not in group_a and all(v not in group for group in groups if group != groups[i]):
                    crossing_edges += 1

    print(crossing_edges)
    if crossing_edges:
        print(" ".join(str(idx + 1) for idx, edge in enumerate(edges) if all(u not in groups or v not in groups for u, v in [edge])))
    else:
        print(0)

