        segments.append((l, r))

    # Precompute which segments are lightened at every position
    # We'll use a segment array
    min_left = [0] * (L + 1)
    for l, r in segments:
        for pos in range(l, r):
            if pos < len(min_left):
                min_left[pos] = min(min_left[pos], min(l, pos))
    # The condition is: every point in dx >= 0 is lightened
    min_right = [min(l - pos, pos) for l, pos in zip(segments, range(L))]
    lighted = [min_left[pos] <= min_right[pos] for pos in range(L)]

    curr = 0
    total = 0
    # max performances within the first p units
    while curr < L - p:
        while curr < L and curr + p <= L and lighted[curr + p]:
            curr += p
            total += 1
    # Now continue until the end
    while curr < L:
        l, r = lighted[curr], curr + 1
        if r - l < t and curr >= L - t:
            break
        # Wait for at least t units
        while l < curr or curr < r:
            l, r = min(min_left[curr], min_right[curr]), min(l, curr)
            if l < curr < r:
                break
            if curr >= L - t:
                break
        if l >= curr:
            break
        curr = l
    print(total)

