    def dfs(u, p):
        visited[u] = True
        parent[u] = p
        size[u] = 1
        for v in (i for i in range(1, n + 1) if edges[u-1][0] == i or edges[u-1][1] == i):
            if not visited[v]:
                depth[v] = depth[u] + 1
                parent[v] = u
                dfs(v, u)
                size[u] += size[v]
                if depth[u] < depth[v]:
                    label_count[labels[v]] = label_count[labels[v]] + 1

